1: import type { Vec3 } from '../contracts/math';
2: import type { TriggerZone } from './types';
3: import { clamp01, distance } from './vec';
4: 
5: const EPS = 1e-6;
6: 
7: export function zoneCenter(zone: TriggerZone): Vec3 {
8:   return zone.center;
9: }
10: 
11: /** True when a ball of `radius` overlaps the zone. */
12: export function zoneContains(zone: TriggerZone, point: Vec3, radius = 0): boolean {
13:   if (zone.shape === 'sphere') {
14:     return distance(point, zone.center) <= zone.radius + radius;
15:   }
16:   return (
17:     Math.abs(point.x - zone.center.x) <= zone.halfExtents.x + radius &&
18:     Math.abs(point.y - zone.center.y) <= zone.halfExtents.y + radius &&
19:     Math.abs(point.z - zone.center.z) <= zone.halfExtents.z + radius
20:   );
21: }
22: 
23: /** 1 at the zone center, 0 at its border. Used for force falloff. */
24: export function zoneNormalizedDepth(zone: TriggerZone, point: Vec3): number {
25:   if (zone.shape === 'sphere') {
26:     if (zone.radius <= EPS) return 0;
27:     return clamp01(1 - distance(point, zone.center) / zone.radius);
28:   }
29:   const h = zone.halfExtents;
30:   const dx = h.x > EPS ? 1 - Math.abs(point.x - zone.center.x) / h.x : 1;
31:   const dy = h.y > EPS ? 1 - Math.abs(point.y - zone.center.y) / h.y : 1;
32:   const dz = h.z > EPS ? 1 - Math.abs(point.z - zone.center.z) / h.z : 1;
33:   return clamp01(Math.min(dx, dy, dz));
34: }
